 // inputs. This explicitly tests a downstream consumer without changing Risk.
 if(lowFinding){const f=ci.riskAssessment.findings.find(f=>f.code===lowFinding);if(!f)throw Error('Missing low-finding fixture');f.evidenceConfidence='LOW';f.evidence=f.evidence.map(e=>({...e,confidence:'LOW'}));}
